def get_config(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate unexpected parameters
    if _extra:
        return _err("VALIDATION_ERROR", "Unexpected parameters provided.", unexpected=list(_extra.keys()))

    # Usage log / rate limit enforcement
    reqlog = _load("request_logs.json")
    if not isinstance(reqlog, list):
        reqlog = []

    def _count_recent(seconds):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=seconds)
        c = 0
        for r in reqlog:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt.astimezone(datetime.timezone.utc).replace(tzinfo=None) >= cutoff:
                c += 1
        return c

    # Simple global rate limit: 120 req/min
    if _count_recent(60) >= 120:
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "get_config",
                "credential_id": None,
                "workspace_id": None,
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            }
        )
        _save("request_logs.json", reqlog)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    # Ambient auth: pick a working active api_key + active workspace combination
    chosen_key = None
    chosen_ws = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws_id = k.get("workspace_id")
        if not isinstance(ws_id, str):
            continue
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if ws and ws.get("status") == "active":
            chosen_key = k
            chosen_ws = ws
            break

    if not chosen_key or not chosen_ws:
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "get_config",
                "credential_id": None,
                "workspace_id": None,
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            }
        )
        _save("request_logs.json", reqlog)
        return _err("UNAUTHORIZED", "No active API key/workspace available for this deployment.")

    # Update last_used_at (mutation must have effect; it always matches chosen_key)
    chosen_key["last_used_at"] = now
    chosen_key["updated_at"] = now
    _save("api_keys.json", api_keys)

    settings = chosen_ws.get("settings")
    if not isinstance(settings, dict):
        settings = {}

    scopes = chosen_key.get("scopes") if isinstance(chosen_key.get("scopes"), list) else []
    scopes_set = set([s for s in scopes if isinstance(s, str)])

    def _can(action_prefix):
        return (f"{action_prefix}:write" in scopes_set) or ("*:*" in scopes_set) or (f"{action_prefix}:*" in scopes_set)

    capabilities = {
        "tasks": {"readable": ("tasks:read" in scopes_set) or ("tasks:*" in scopes_set) or ("*:*" in scopes_set), "writable": _can("tasks")},
        "docs": {"readable": ("docs:read" in scopes_set) or ("docs:*" in scopes_set) or ("*:*" in scopes_set), "writable": _can("docs")},
    }

    resp = {
        "workspace": {
            "id": chosen_ws.get("id"),
            "slug": chosen_ws.get("slug"),
            "name": chosen_ws.get("name"),
            "default_timezone": chosen_ws.get("default_timezone"),
            "status": chosen_ws.get("status"),
        },
        "settings": settings,
        "capabilities": capabilities,
        "scopes": sorted(list(scopes_set)),
    }

    reqlog.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "get_config",
            "credential_id": chosen_key.get("id"),
            "workspace_id": chosen_ws.get("id"),
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
    )
    _save("request_logs.json", reqlog)
    return resp

def list_tasks(workspace_id=None, dartboard_id=None, parent_task_id=None, assignee_id=None, status=None, priority=None, size=None, tag_name=None, query=None, due_before=None, due_after=None, start_before=None, start_after=None, completed_before=None, completed_after=None, is_trashed=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            raise ValueError(f"{field} must be a valid RFC3339 date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _matches_pat(val, pat):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _has_scope(scopes, required):
        if not required:
            return True
        if not isinstance(scopes, list):
            return False
        s = set([x for x in scopes if isinstance(x, str)])
        req = set(required)
        if req.issubset(s):
            return True
        # allow global wildcards
        if any(r.endswith(":read") for r in req) and ("*:read" in s or "*:*" in s):
            return True
        if any(r.endswith(":write") for r in req) and ("*:write" in s or "*:*" in s):
            return True
        # allow resource wildcards like tasks:* (covers tasks:read / tasks:write)
        for r in req:
            if ":" in r:
                res, _act = r.split(":", 1)
                if f"{res}:*" in s or "*:*" in s:
                    return True
        return False

    def _choose_key(required_scopes):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        wss = _load("workspaces.json")
        if not isinstance(wss, list):
            wss = []
        ws_by_id = {w.get("id"): w for w in wss if isinstance(w, dict) and isinstance(w.get("id"), str)}
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if not _has_scope(k.get("scopes"), required_scopes):
                continue
            wid = k.get("workspace_id")
            ws = ws_by_id.get(wid)
            if not ws:
                continue
            if ws.get("status") not in ("active", "suspended"):
                continue
            candidates.append((k, ws))
        if not candidates:
            return None, None
        # if caller supplied workspace_id, constrain to it
        if isinstance(workspace_id, str):
            for k, ws in candidates:
                if k.get("workspace_id") == workspace_id:
                    return k, ws
        return candidates[0]

    def _log(endpoint, api_key_id, workspace_id_log, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id_log,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_z(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limited(api_key_id):
        if not api_key_id:
            return False
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at") or r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                c += 1
        return c >= 120  # 120/min per key

    # ---- validate inputs ----
    if _extra:
        # vendor schema says additionalProperties=false; treat as validation error
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "Unexpected parameters provided.")
        return _err("VALIDATION_ERROR", "Unexpected parameters provided.", unexpected=list(_extra.keys()))

    if workspace_id is not None and not _matches_pat(workspace_id, r"^dart_ws_[0-9A-Z]{18,}$"):
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "workspace_id is not well-formed.")
        return _err("VALIDATION_ERROR", "workspace_id is not well-formed.")
    if parent_task_id is not None and not _matches_pat(parent_task_id, r"^dart_tsk_[0-9A-Z]{18,}$"):
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "parent_task_id is not well-formed.")
        return _err("VALIDATION_ERROR", "parent_task_id is not well-formed.")
    if assignee_id is not None and not _matches_pat(assignee_id, r"^dart_usr_[0-9A-Z]{18,}$"):
        # This is the defect observed: previous code rejected a valid-looking id because it wasn't a user id
        # However, per schema it MUST match dart_usr_...; return a consistent error message.
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "assignee_id is not well-formed.")
        return _err("VALIDATION_ERROR", "assignee_id is not well-formed.")
    if dartboard_id is not None and not isinstance(dartboard_id, str):
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "dartboard_id must be a string.")
        return _err("VALIDATION_ERROR", "dartboard_id must be a string.")
    if tag_name is not None and not isinstance(tag_name, str):
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "tag_name must be a string.")
        return _err("VALIDATION_ERROR", "tag_name must be a string.")
    if query is not None and not isinstance(query, str):
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "query must be a string.")
        return _err("VALIDATION_ERROR", "query must be a string.")
    if is_trashed is not None and not isinstance(is_trashed, bool):
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "is_trashed must be a boolean.")
        return _err("VALIDATION_ERROR", "is_trashed must be a boolean.")

    allowed_status = {"backlog", "todo", "in_progress", "blocked", "done", "cancelled"}
    allowed_priority = {"low", "medium", "high", "urgent"}
    allowed_size = {"xs", "s", "m", "l", "xl"}
    allowed_sort = {"created_at", "updated_at", "due_at", "start_at", "completed_at", "priority", "status"}
    allowed_order = {"asc", "desc"}

    if status is not None and status not in allowed_status:
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "Invalid status.")
        return _err("VALIDATION_ERROR", "status must be one of " + ", ".join(sorted(allowed_status)))
    if priority is not None and priority not in allowed_priority:
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "Invalid priority.")
        return _err("VALIDATION_ERROR", "priority must be one of " + ", ".join(sorted(allowed_priority)))
    if size is not None and size not in allowed_size:
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "Invalid size.")
        return _err("VALIDATION_ERROR", "size must be one of " + ", ".join(sorted(allowed_size)))
    if sort is not None and sort not in allowed_sort:
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "Invalid sort.")
        return _err("VALIDATION_ERROR", "sort must be one of " + ", ".join(sorted(allowed_sort)))
    if order is not None and order not in allowed_order:
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "Invalid order.")
        return _err("VALIDATION_ERROR", "order must be one of asc, desc")
    if limit is not None:
        if not isinstance(limit, int):
            k, ws = _choose_key(["tasks:read"])
            _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "limit must be an integer.")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            k, ws = _choose_key(["tasks:read"])
            _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", "limit out of range.")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    else:
        limit = 50

    try:
        due_before_dt = _parse_dt(due_before, "due_before")
        due_after_dt = _parse_dt(due_after, "due_after")
        start_before_dt = _parse_dt(start_before, "start_before")
        start_after_dt = _parse_dt(start_after, "start_after")
        completed_before_dt = _parse_dt(completed_before, "completed_before")
        completed_after_dt = _parse_dt(completed_after, "completed_after")
    except ValueError as e:
        k, ws = _choose_key(["tasks:read"])
        _log("list_tasks", k.get("id") if k else None, (ws.get("id") if ws else None), "error", "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", str(e))

    # ---- auth & rate limit ----
    key, ws = _choose_key(["tasks:read"])
    if not key:
        _log("list_tasks", None, None, "error", "UNAUTHORIZED", "No active API key with required scope tasks:read found.")
        return _err("UNAUTHORIZED", "No active API key with required scope tasks:read found.")

    if _rate_limited(key.get("id")):
        _log("list_tasks", key.get("id"), key.get("workspace_id"), "error", "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # update key last_used_at
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for kk in api_keys:
            if isinstance(kk, dict) and kk.get("id") == key.get("id"):
                kk["last_used_at"] = _now_z()
                kk["updated_at"] = _now_z()
                break
        _save("api_keys.json", api_keys)

    effective_ws_id = key.get("workspace_id")

    # forbid cross-workspace: if workspace_id param provided and not same, treat as unauthorized (scope is per workspace)
    if workspace_id is not None and workspace_id != effective_ws_id:
        _log("list_tasks", key.get("id"), effective_ws_id, "error", "UNAUTHORIZED", "API key is not authorized for the requested workspace.")
        return _err("UNAUTHORIZED", "API key is not authorized for the requested workspace.")

    # ---- fetch and filter ----
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    def _dt_from_row(val):
        if not isinstance(val, str) or not val:
            return None
        try:
            dt = datetime.datetime.fromisoformat(val.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    q = query.lower().strip() if isinstance(query, str) else None
    tag_norm = tag_name.strip().lower() if isinstance(tag_name, str) else None

    filtered = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("workspace_id") != effective_ws_id:
            continue

        # trash handling: business rule says default exclude trashed unless internal flag.
        # This tool exposes is_trashed param; if not provided, default False (non-trashed only)
        row_trashed = bool(t.get("is_trashed"))
        if is_trashed is None:
            if row_trashed:
                continue
        else:
            if row_trashed != is_trashed:
                continue

        if dartboard_id is not None and t.get("dartboard_id") != dartboard_id:
            continue
        if parent_task_id is not None and t.get("parent_task_id") != parent_task_id:
            continue
        if status is not None and t.get("status") != status:
            continue
        if priority is not None and t.get("priority") != priority:
            continue
        if size is not None and t.get("size") != size:
            continue
        if assignee_id is not None:
            a = t.get("assignee_ids")
            if not isinstance(a, list) or assignee_id not in a:
                continue
        if tag_norm is not None:
            tags = t.get("tag_names")
            if not isinstance(tags, list):
                continue
            if tag_norm not in [str(x).strip().lower() for x in tags if isinstance(x, str)]:
                continue

        if q:
            title = (t.get("title") or "")
            desc = (t.get("description") or "")
            if not isinstance(title, str):
                title = str(title)
            if not isinstance(desc, str):
                desc = str(desc)
            if q not in title.lower() and q not in desc.lower():
                continue

        due_dt = _dt_from_row(t.get("due_at"))
        if due_before_dt is not None:
            if due_dt is None or not (due_dt < due_before_dt):
                continue
        if due_after_dt is not None:
            if due_dt is None or not (due_dt > due_after_dt):
                continue

        start_dt = _dt_from_row(t.get("start_at"))
        if start_before_dt is not None:
            if start_dt is None or not (start_dt < start_before_dt):
                continue
        if start_after_dt is not None:
            if start_dt is None or not (start_dt > start_after_dt):
                continue

        comp_dt = _dt_from_row(t.get("completed_at"))
        if completed_before_dt is not None:
            if comp_dt is None or not (comp_dt < completed_before_dt):
                continue
        if completed_after_dt is not None:
            if comp_dt is None or not (comp_dt > completed_after_dt):
                continue

        filtered.append(t)

    # sorting
    sort_field = sort or "created_at"
    sort_dir = (order or "desc").lower()

    def _sort_key(row):
        v = row.get(sort_field)
        if sort_field in ("created_at", "updated_at", "due_at", "start_at", "completed_at"):
            dt = _dt_from_row(v)
            # None sorts last for desc, first for asc; normalize to min/max
            if dt is None:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if sort_dir == "asc" else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            return dt
        return "" if v is None else str(v)

    reverse = (sort_dir == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    # cursor: vendor uses opaque; here accept cursor as "after:<task_id>" or raw task_id.
    start_index = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("list_tasks", key.get("id"), effective_ws_id, "error", "VALIDATION_ERROR", "cursor must be a string.")
            return _err("VALIDATION_ERROR", "cursor must be a string")
        cur_id = cursor
        if cursor.startswith("after:"):
            cur_id = cursor[6:]
        # find the first occurrence; if not found, start at 0 (real APIs often treat unknown cursor as invalid; but spec doesn't say)
        for i, row in enumerate(filtered):
            if row.get("id") == cur_id:
                start_index = i + 1
                break

    page = filtered[start_index:start_index + limit]
    has_more = (start_index + limit) < len(filtered)
    next_cursor = None
    if has_more and page:
        next_cursor = "after:" + str(page[-1].get("id"))

    _log("list_tasks", key.get("id"), effective_ws_id, "ok")

    return {
        "tasks": page,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": limit,
        "cursor": cursor,
        "sort": sort_field,
        "order": sort_dir,
        "workspace_id": effective_ws_id,
    }

def create_task(workspace_id, title, dartboard_id=None, parent_task_id=None, description=None, status=None, priority=None, size=None, start_at=None, due_at=None, assignee_ids=None, tag_names=None, **_extra):
    import json, os, datetime, time, re, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if _extra:
        return _err("VALIDATION_ERROR", "Unexpected parameters provided.", unexpected=list(_extra.keys()))

    if not isinstance(workspace_id, str) or not re.match(r"^dart_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is not well-formed.")
    if not isinstance(title, str) or title.strip() == "":
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if dartboard_id is not None and not isinstance(dartboard_id, str):
        return _err("VALIDATION_ERROR", "dartboard_id must be a string.")
    if parent_task_id is not None:
        if not isinstance(parent_task_id, str) or not re.match(r"^dart_tsk_[0-9A-Z]{18,}$", parent_task_id):
            return _err("VALIDATION_ERROR", "parent_task_id is not well-formed.")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string.")
    if status is not None and status not in ["backlog", "todo", "in_progress", "blocked", "done", "cancelled"]:
        return _err("VALIDATION_ERROR", "Invalid status.")
    if priority is not None and priority not in ["low", "medium", "high", "urgent"]:
        return _err("VALIDATION_ERROR", "Invalid priority.")
    if size is not None and size not in ["xs", "s", "m", "l", "xl"]:
        return _err("VALIDATION_ERROR", "Invalid size.")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string.")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be RFC3339 date-time.")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc)
        out = dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return out, None

    start_at_norm, e = _parse_dt(start_at, "start_at")
    if e:
        return e
    due_at_norm, e = _parse_dt(due_at, "due_at")
    if e:
        return e

    if start_at_norm and due_at_norm:
        sdt = datetime.datetime.fromisoformat(start_at_norm.replace("Z", "+00:00"))
        ddt = datetime.datetime.fromisoformat(due_at_norm.replace("Z", "+00:00"))
        if sdt > ddt:
            return _err("VALIDATION_ERROR", "start_at must be <= due_at.")

    if assignee_ids is None:
        assignee_ids = []
    if tag_names is None:
        tag_names = []

    if not isinstance(assignee_ids, list):
        return _err("VALIDATION_ERROR", "assignee_ids must be an array.")
    if not isinstance(tag_names, list):
        return _err("VALIDATION_ERROR", "tag_names must be an array.")

    for a in assignee_ids:
        if not isinstance(a, str) or not re.match(r"^dart_usr_[0-9A-Z]{18,}$", a):
            return _err("VALIDATION_ERROR", "assignee_ids contains an invalid user id.")
    if len(set(assignee_ids)) != len(assignee_ids):
        return _err("VALIDATION_ERROR", "assignee_ids must not contain duplicates.")

    clean_tags = []
    seen = set()
    for tg in tag_names:
        if not isinstance(tg, str) or tg.strip() == "":
            return _err("VALIDATION_ERROR", "tag_names must contain non-empty strings.")
        if tg not in seen:
            seen.add(tg)
            clean_tags.append(tg)

    reqlog = _load("request_logs.json")
    if not isinstance(reqlog, list):
        reqlog = []

    def _count_recent(seconds):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=seconds)
        c = 0
        for r in reqlog:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt.astimezone(datetime.timezone.utc).replace(tzinfo=None) >= cutoff:
                c += 1
        return c

    if _count_recent(60) >= 120:
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "create_task",
                "credential_id": None,
                "workspace_id": workspace_id,
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            }
        )
        _save("request_logs.json", reqlog)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    # Auth: must have active api_key for this workspace and active workspace
    chosen_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and k.get("workspace_id") == workspace_id:
            chosen_key = k
            break
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not chosen_key or not ws or ws.get("status") != "active":
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "create_task",
                "credential_id": chosen_key.get("id") if chosen_key else None,
                "workspace_id": workspace_id,
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            }
        )
        _save("request_logs.json", reqlog)
        return _err("UNAUTHORIZED", "Not authorized for this workspace.")

    # Validate assignees exist and active in workspace
    active_users = {u.get("id") for u in users if isinstance(u, dict) and u.get("workspace_id") == workspace_id and u.get("status") == "active"}
    for a in assignee_ids:
        if a not in active_users:
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "create_task",
                    "credential_id": chosen_key.get("id"),
                    "workspace_id": workspace_id,
                    "status": "NOT_FOUND",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now,
                }
            )
            _save("request_logs.json", reqlog)
            return _err("NOT_FOUND", f"Assignee user not found or not active: {a}")

    # Validate parent task reference & no cycles (new task can't create cycle unless parent chain includes placeholder; still validate parent exists)
    if parent_task_id is not None:
        parent = next((t for t in tasks if isinstance(t, dict) and t.get("id") == parent_task_id and t.get("workspace_id") == workspace_id), None)
        if not parent:
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "create_task",
                    "credential_id": chosen_key.get("id"),
                    "workspace_id": workspace_id,
                    "status": "NOT_FOUND",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now,
                }
            )
            _save("request_logs.json", reqlog)
            return _err("NOT_FOUND", "parent_task_id not found in workspace.")
        # New task has no id yet; cycles can't exist unless parent chain is already cyclic; check defensively
        seen = set()
        cur = parent
        while cur and cur.get("parent_task_id"):
            pid = cur.get("parent_task_id")
            if pid in seen:
                return _err("CONFLICT", "Parent task hierarchy contains a cycle.")
            seen.add(pid)
            cur = next((t for t in tasks if isinstance(t, dict) and t.get("id") == pid and t.get("workspace_id") == workspace_id), None)

    # Create id
    alphabet = string.ascii_uppercase + string.digits

    def _gen_id(prefix):
        while True:
            s = "".join(random.choice(alphabet) for _ in range(20))
            cid = f"{prefix}{s}"
            if not any(isinstance(r, dict) and r.get("id") == cid for r in tasks):
                return cid

    task_id = _gen_id("dart_tsk_")

    final_status = status or "backlog"
    completed_at = None
    if final_status == "done":
        completed_at = now

    task = {
        "id": task_id,
        "workspace_id": workspace_id,
        "dartboard_id": dartboard_id,
        "parent_task_id": parent_task_id,
        "title": title,
        "description": description,
        "status": final_status,
        "priority": priority,
        "size": size,
        "start_at": start_at_norm,
        "due_at": due_at_norm,
        "completed_at": completed_at,
        "assignee_ids": assignee_ids,
        "tag_names": clean_tags,
        "is_trashed": False,
        "trashed_at": None,
        "created_by_user_id": None,
        "updated_by_user_id": None,
        "created_at": now,
        "updated_at": now,
    }

    tasks.append(task)
    _save("tasks.json", tasks)

    chosen_key["last_used_at"] = now
    chosen_key["updated_at"] = now
    _save("api_keys.json", api_keys)

    reqlog.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create_task",
            "credential_id": chosen_key.get("id"),
            "workspace_id": workspace_id,
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
    )
    _save("request_logs.json", reqlog)
    return {"task": task}

def get_task(task_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, api_key_id=None, workspace_id=None, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status,
                "error_code": error_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_z(),
            }
        )
        _save("request_logs.json", logs)

    def _has_scope(scopes, required):
        if not required:
            return True
        if not isinstance(scopes, list):
            return False
        s = set([x for x in scopes if isinstance(x, str)])
        req = set(required)
        if req.issubset(s):
            return True
        if any(r.endswith(":read") for r in req) and ("*:read" in s or "*:*" in s):
            return True
        for r in req:
            if ":" in r:
                res, _act = r.split(":", 1)
                if f"{res}:*" in s or "*:*" in s:
                    return True
        return False

    def _pick_auth_workspace(required_scopes):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        # pick an active key whose workspace is active and has required scopes
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            wsid = k.get("workspace_id")
            ws = ws_by_id.get(wsid)
            if not ws or ws.get("status") != "active":
                continue
            if not _has_scope(k.get("scopes"), required_scopes):
                continue
            return k, ws
        return None, None

    try:
        # Relax validation: accept any non-empty string id; do NOT hard-reject if pattern doesn't match.
        if not isinstance(task_id, str) or not task_id.strip():
            _log("get_task", "error", error_code="VALIDATION_ERROR", message="task_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "task_id must be a non-empty string")

        api_key, ws = _pick_auth_workspace(["tasks:read"])
        if not api_key:
            _log("get_task", "error", error_code="UNAUTHORIZED", message="No active API key with tasks:read scope found")
            return _err("UNAUTHORIZED", "No active API key authorized for this operation")

        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        # Only within caller workspace; exclude trashed by default
        row = None
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("id") == task_id and t.get("workspace_id") == ws.get("id"):
                row = t
                break

        if not row or row.get("is_trashed") is True:
            _log("get_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND", message="Task not found")
            return _err("NOT_FOUND", "Task not found")

        # update key last_used_at
        now = _now_z()
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = k.get("updated_at") or now
                    break
            _save("api_keys.json", api_keys)

        _log("get_task", "ok", api_key_id=api_key.get("id"), workspace_id=ws.get("id"))
        return {"task": row}
    except Exception as e:
        _log("get_task", "error", error_code="VALIDATION_ERROR", message=str(e))
        return _err("VALIDATION_ERROR", "Internal error", detail=str(e))

def update_task(task_id, title=None, description=None, status=None, priority=None, size=None, dartboard_id=None, parent_task_id=None, start_at=None, due_at=None, completed_at=None, assignee_ids=None, tag_names=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, api_key_id=None, workspace_id=None, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status_s,
                "error_code": error_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_z(),
            }
        )
        _save("request_logs.json", logs)

    def _has_scope(scopes, required):
        if not required:
            return True
        if not isinstance(scopes, list):
            return False
        s = set([x for x in scopes if isinstance(x, str)])
        req = set(required)
        if req.issubset(s):
            return True
        if any(r.endswith(":write") for r in req) and ("*:write" in s or "*:*" in s):
            return True
        for r in req:
            if ":" in r:
                res, _act = r.split(":", 1)
                if f"{res}:*" in s or "*:*" in s:
                    return True
        return False

    def _pick_auth_workspace(required_scopes):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            wsid = k.get("workspace_id")
            ws = ws_by_id.get(wsid)
            if not ws or ws.get("status") != "active":
                continue
            if not _has_scope(k.get("scopes"), required_scopes):
                continue
            return k, ws
        return None, None

    def _parse_dt(val, field):
        if val is None:
            return None, None
        if not isinstance(val, str) or not val.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            dt = datetime.datetime.fromisoformat(val.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt_utc = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt_utc.isoformat().replace("+00:00", "Z"), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _would_cycle(tasks_by_id, start_id, new_parent_id):
        # detect if assigning new_parent_id creates a cycle by walking up parents
        cur = new_parent_id
        seen = set()
        while cur:
            if cur == start_id:
                return True
            if cur in seen:
                # existing corruption -> treat as cycle risk
                return True
            seen.add(cur)
            t = tasks_by_id.get(cur)
            if not isinstance(t, dict):
                return False
            cur = t.get("parent_task_id")
        return False

    try:
        # Relax validation: accept any non-empty task_id string; don't hard-reject pattern mismatches.
        if not isinstance(task_id, str) or not task_id.strip():
            _log("update_task", "error", error_code="VALIDATION_ERROR", message="task_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "task_id must be a non-empty string")

        api_key, ws = _pick_auth_workspace(["tasks:write"])
        if not api_key:
            _log("update_task", "error", error_code="UNAUTHORIZED", message="No active API key with tasks:write scope found")
            return _err("UNAUTHORIZED", "No active API key authorized for this operation")

        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []
        idx = None
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and t.get("id") == task_id and t.get("workspace_id") == ws.get("id"):
                idx = i
                break
        if idx is None:
            _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND", message="Task not found")
            return _err("NOT_FOUND", "Task not found")

        task = tasks[idx]
        if task.get("is_trashed") is True:
            _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="INVALID_TRANSITION", message="Cannot update a trashed task")
            return _err("INVALID_TRANSITION", "Cannot update a trashed task")

        # Validate and compute updates
        updates = {}
        if title is not None:
            if not isinstance(title, str) or not title.strip():
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="title must be a non-empty string")
                return _err("VALIDATION_ERROR", "title must be a non-empty string")
            updates["title"] = title

        if description is not None:
            if not isinstance(description, str):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="description must be a string")
                return _err("VALIDATION_ERROR", "description must be a string")
            updates["description"] = description

        allowed_status = {"backlog", "todo", "in_progress", "blocked", "done", "cancelled"}
        transitions = {
            "backlog": ["todo", "in_progress", "cancelled"],
            "todo": ["in_progress", "blocked", "cancelled", "done"],
            "in_progress": ["blocked", "done", "cancelled", "todo"],
            "blocked": ["in_progress", "todo", "cancelled"],
            "done": ["todo", "in_progress"],
            "cancelled": ["todo", "backlog"],
        }
        if status is not None:
            if not isinstance(status, str) or status not in allowed_status:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="status must be one of backlog,todo,in_progress,blocked,done,cancelled")
                return _err("VALIDATION_ERROR", "status must be one of backlog,todo,in_progress,blocked,done,cancelled")
            cur = task.get("status")
            if cur != status:
                if cur not in transitions or status not in transitions.get(cur, []):
                    _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="INVALID_TRANSITION", message=f"Illegal status transition {cur} -> {status}")
                    return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}")
                updates["status"] = status

        allowed_priority = {"low", "medium", "high", "urgent"}
        if priority is not None:
            if not isinstance(priority, str) or priority not in allowed_priority:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="priority must be one of low,medium,high,urgent")
                return _err("VALIDATION_ERROR", "priority must be one of low,medium,high,urgent")
            updates["priority"] = priority

        allowed_size = {"xs", "s", "m", "l", "xl"}
        if size is not None:
            if not isinstance(size, str) or size not in allowed_size:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="size must be one of xs,s,m,l,xl")
                return _err("VALIDATION_ERROR", "size must be one of xs,s,m,l,xl")
            updates["size"] = size

        if dartboard_id is not None:
            if not isinstance(dartboard_id, str):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="dartboard_id must be a string")
                return _err("VALIDATION_ERROR", "dartboard_id must be a string")
            updates["dartboard_id"] = dartboard_id

        # dates
        start_iso, e1 = _parse_dt(start_at, "start_at")
        if e1:
            _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code=e1["error"]["code"], message=e1["error"]["message"])
            return e1
        due_iso, e2 = _parse_dt(due_at, "due_at")
        if e2:
            _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code=e2["error"]["code"], message=e2["error"]["message"])
            return e2

        if start_at is not None:
            updates["start_at"] = start_iso
        if due_at is not None:
            updates["due_at"] = due_iso

        # enforce start_at <= due_at using new or existing values
        eff_start = updates.get("start_at", task.get("start_at"))
        eff_due = updates.get("due_at", task.get("due_at"))
        if eff_start and eff_due:
            ds, e3 = _parse_dt(eff_start, "start_at")
            dd, e4 = _parse_dt(eff_due, "due_at")
            if e3 or e4:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="Existing start_at/due_at are invalid")
                return _err("VALIDATION_ERROR", "Existing start_at/due_at are invalid")
            if ds > dd:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="due_at must be >= start_at when both are present")
                return _err("VALIDATION_ERROR", "due_at must be >= start_at when both are present")

        # completed_at is trigger-managed by status; clients cannot set inconsistently
        if completed_at is not None:
            # allow caller to pass, but enforce rule
            comp_iso, e5 = _parse_dt(completed_at, "completed_at")
            if e5:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code=e5["error"]["code"], message=e5["error"]["message"])
                return e5
            eff_status = updates.get("status", task.get("status"))
            if eff_status != "done":
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="completed_at can only be set when status is 'done'")
                return _err("VALIDATION_ERROR", "completed_at can only be set when status is 'done'")
            # accept but will still be overwritten to now for consistency with server behavior? keep provided if done
            updates["completed_at"] = comp_iso

        # assignees: must be active users in same workspace and unique
        if assignee_ids is not None:
            if not isinstance(assignee_ids, list):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="assignee_ids must be an array of user ids")
                return _err("VALIDATION_ERROR", "assignee_ids must be an array of user ids")
            if any(not isinstance(x, str) or not x.strip() for x in assignee_ids):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="assignee_ids must be an array of non-empty strings")
                return _err("VALIDATION_ERROR", "assignee_ids must be an array of non-empty strings")
            if len(set(assignee_ids)) != len(assignee_ids):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="assignee_ids contains duplicates")
                return _err("VALIDATION_ERROR", "assignee_ids contains duplicates")

            users = _load("users.json")
            if not isinstance(users, list):
                users = []
            active_user_ids = set(
                u.get("id")
                for u in users
                if isinstance(u, dict)
                and u.get("workspace_id") == ws.get("id")
                and u.get("status") == "active"
                and isinstance(u.get("id"), str)
            )
            missing = [uid for uid in assignee_ids if uid not in active_user_ids]
            if missing:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND", message="One or more assignees not found or not active in this workspace")
                return _err("NOT_FOUND", "One or more assignees not found or not active in this workspace", missing_assignee_ids=missing)

            updates["assignee_ids"] = assignee_ids

        # tags: unique, non-empty strings
        if tag_names is not None:
            if not isinstance(tag_names, list):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="tag_names must be an array of strings")
                return _err("VALIDATION_ERROR", "tag_names must be an array of strings")
            norm = []
            for t in tag_names:
                if not isinstance(t, str):
                    _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="tag_names must be an array of strings")
                    return _err("VALIDATION_ERROR", "tag_names must be an array of strings")
                tt = t.strip()
                if not tt:
                    _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="tag_names must not include empty strings")
                    return _err("VALIDATION_ERROR", "tag_names must not include empty strings")
                norm.append(tt)
            if len(set(norm)) != len(norm):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="tag_names contains duplicates")
                return _err("VALIDATION_ERROR", "tag_names contains duplicates")
            updates["tag_names"] = norm

        # parent task: must exist in same workspace, cannot create cycles
        if parent_task_id is not None:
            if parent_task_id is not None and (not isinstance(parent_task_id, str) or not parent_task_id.strip()):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="parent_task_id must be a non-empty string when provided")
                return _err("VALIDATION_ERROR", "parent_task_id must be a non-empty string when provided")
            if parent_task_id == task_id:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="parent_task_id cannot equal task_id")
                return _err("VALIDATION_ERROR", "parent_task_id cannot equal task_id")

            tasks_by_id = {t.get("id"): t for t in tasks if isinstance(t, dict) and t.get("workspace_id") == ws.get("id")}
            parent = tasks_by_id.get(parent_task_id)
            if not parent:
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND", message="parent_task_id not found in this workspace")
                return _err("NOT_FOUND", "parent_task_id not found in this workspace")
            if _would_cycle(tasks_by_id, task_id, parent_task_id):
                _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="CONFLICT", message="parent_task_id would create a cycle")
                return _err("CONFLICT", "parent_task_id would create a cycle")
            updates["parent_task_id"] = parent_task_id

        if not updates:
            # No-op update should still be rejected as no effect (per contract)
            _log("update_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="No fields to update")
            return _err("VALIDATION_ERROR", "No fields to update")

        now = _now_z()

        # Apply status->completed_at trigger semantics
        new_status = updates.get("status", task.get("status"))
        if "status" in updates:
            if new_status == "done":
                # set completion time if not provided
                if "completed_at" not in updates:
                    updates["completed_at"] = now
            else:
                # leaving done clears completion
                if task.get("status") == "done":
                    updates["completed_at"] = None
                else:
                    # if client tried to set completed_at while not done we already rejected
                    pass
        else:
            # if client tried to set completed_at while status remains existing done, allow above already
            pass

        # enforce completed_at iff status=='done'
        eff_completed = updates.get("completed_at", task.get("completed_at"))
        if new_status == "done":
            if eff_completed is None:
                updates["completed_at"] = now
        else:
            if eff_completed is not None:
                updates["completed_at"] = None

        # persist
        for k, v in updates.items():
            task[k] = v
        task["updated_at"] = now
        # keep editor unknown; no user auth in surface
        if "updated_by_user_id" not in task:
            task["updated_by_user_id"] = task.get("updated_by_user_id")

        tasks[idx] = task
        _save("tasks.json", tasks)

        # update key last_used_at
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = k.get("updated_at") or now
                    break
            _save("api_keys.json", api_keys)

        _log("update_task", "ok", api_key_id=api_key.get("id"), workspace_id=ws.get("id"))
        return {"task": task}
    except Exception as e:
        _log("update_task", "error", error_code="VALIDATION_ERROR", message=str(e))
        return _err("VALIDATION_ERROR", "Internal error", detail=str(e))

def delete_task(task_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, api_key_id=None, workspace_id=None, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status,
                "error_code": error_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_z(),
            }
        )
        _save("request_logs.json", logs)

    def _has_scope(scopes, required):
        if not required:
            return True
        if not isinstance(scopes, list):
            return False
        s = set([x for x in scopes if isinstance(x, str)])
        req = set(required)
        if req.issubset(s):
            return True
        if any(r.endswith(":write") for r in req) and ("*:write" in s or "*:*" in s):
            return True
        for r in req:
            if ":" in r:
                res, _act = r.split(":", 1)
                if f"{res}:*" in s or "*:*" in s:
                    return True
        return False

    def _pick_auth_workspace(required_scopes):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            wsid = k.get("workspace_id")
            ws = ws_by_id.get(wsid)
            if not ws or ws.get("status") != "active":
                continue
            if not _has_scope(k.get("scopes"), required_scopes):
                continue
            return k, ws
        return None, None

    try:
        if not isinstance(task_id, str) or not task_id.strip():
            _log("delete_task", "error", error_code="VALIDATION_ERROR", message="task_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "task_id must be a non-empty string")

        api_key, ws = _pick_auth_workspace(["tasks:write"])
        if not api_key:
            _log("delete_task", "error", error_code="UNAUTHORIZED", message="No active API key with tasks:write scope found")
            return _err("UNAUTHORIZED", "No active API key authorized for this operation")

        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        idx = None
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and t.get("id") == task_id and t.get("workspace_id") == ws.get("id"):
                idx = i
                break
        if idx is None:
            _log("delete_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND", message="Task not found")
            return _err("NOT_FOUND", "Task not found")

        task = tasks[idx]
        if task.get("is_trashed") is True:
            _log("delete_task", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="CONFLICT", message="Task is already trashed")
            return _err("CONFLICT", "Task is already trashed")

        now = _now_z()
        # soft delete: only touch trash fields + updated_at (+updated_by_user_id allowed)
        task["is_trashed"] = True
        task["trashed_at"] = now
        task["updated_at"] = now

        tasks[idx] = task
        _save("tasks.json", tasks)

        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = k.get("updated_at") or now
                    break
            _save("api_keys.json", api_keys)

        _log("delete_task", "ok", api_key_id=api_key.get("id"), workspace_id=ws.get("id"))
        return {"task": task}
    except Exception as e:
        _log("delete_task", "error", error_code="VALIDATION_ERROR", message=str(e))
        return _err("VALIDATION_ERROR", "Internal error", detail=str(e))

def list_docs(workspace_id=None, folder_id=None, status=None, title=None, query=None, is_trashed=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    api_keys = _load("api_keys.json")
    reqlog = _load("request_logs.json")
    if not isinstance(reqlog, list):
        reqlog = []

    key = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        scopes = k.get("scopes")
        if not isinstance(scopes, list):
            continue
        if ("docs:read" in scopes) or ("*:*" in scopes) or ("docs:*" in scopes) or ("docs:write" in scopes):
            key = k
            break

    def _log_and_return(resp, status_code="ok", error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": f"dart_req_{int(time.time()*1000)}",
            "endpoint": "list_docs",
            "api_key_id": key.get("id") if isinstance(key, dict) else None,
            "workspace_id": key.get("workspace_id") if isinstance(key, dict) else None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        reqlog.append(entry)
        _save("request_logs.json", reqlog)
        if isinstance(key, dict):
            for kk in api_keys:
                if isinstance(kk, dict) and kk.get("id") == key.get("id"):
                    kk["last_used_at"] = now
                    kk["updated_at"] = kk.get("updated_at") or now
                    break
            _save("api_keys.json", api_keys)
        return resp

    if key is None:
        return _log_and_return(_err("UNAUTHORIZED", "No active API key with required scope docs:read found."), status_code="error", error_code="UNAUTHORIZED")

    # rate limit: 120/min per key for reads if request_logs exists
    window_start = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
    recent = 0
    for r in reqlog:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") == key.get("id") and r.get("timestamp") and r["timestamp"] >= window_start:
            recent += 1
    if recent >= 120:
        return _log_and_return(_err("RATE_LIMIT", "Rate limit exceeded."), status_code="error", error_code="RATE_LIMIT")

    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^dart_ws_[0-9A-Z]{18,}$", workspace_id):
            return _log_and_return(_err("VALIDATION_ERROR", "workspace_id is invalid."), status_code="error", error_code="VALIDATION_ERROR")
        if workspace_id != key.get("workspace_id"):
            # scoped to key workspace
            return _log_and_return(_err("UNAUTHORIZED", "API key not authorized for requested workspace."), status_code="error", error_code="UNAUTHORIZED")
        ws_id = workspace_id
    else:
        ws_id = key.get("workspace_id")

    if folder_id is not None and not isinstance(folder_id, str):
        return _log_and_return(_err("VALIDATION_ERROR", "folder_id must be a string."), status_code="error", error_code="VALIDATION_ERROR")
    allowed_status = {"draft","published","archived"}
    if status is not None and status not in allowed_status:
        return _log_and_return(_err("VALIDATION_ERROR", "status is invalid."), status_code="error", error_code="VALIDATION_ERROR")
    if title is not None and not isinstance(title, str):
        return _log_and_return(_err("VALIDATION_ERROR", "title must be a string."), status_code="error", error_code="VALIDATION_ERROR")
    if query is not None and not isinstance(query, str):
        return _log_and_return(_err("VALIDATION_ERROR", "query must be a string."), status_code="error", error_code="VALIDATION_ERROR")
    if is_trashed is not None and not isinstance(is_trashed, bool):
        return _log_and_return(_err("VALIDATION_ERROR", "is_trashed must be a boolean."), status_code="error", error_code="VALIDATION_ERROR")

    sort_allowed = {"created_at","updated_at","title"}
    if sort is None:
        sort = "updated_at"
    if sort not in sort_allowed:
        return _log_and_return(_err("VALIDATION_ERROR", "sort is invalid."), status_code="error", error_code="VALIDATION_ERROR")

    order_allowed = {"asc","desc"}
    if order is None:
        order = "desc"
    if order not in order_allowed:
        return _log_and_return(_err("VALIDATION_ERROR", "order is invalid."), status_code="error", error_code="VALIDATION_ERROR")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 200."), status_code="error", error_code="VALIDATION_ERROR")

    # cursor format: base64("offset:<int>")
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid."), status_code="error", error_code="VALIDATION_ERROR")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid."), status_code="error", error_code="VALIDATION_ERROR")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid."), status_code="error", error_code="VALIDATION_ERROR")
        except Exception:
            return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid."), status_code="error", error_code="VALIDATION_ERROR")

    docs = _load("docs.json")
    if not isinstance(docs, list):
        docs = []

    def _match(d):
        if not isinstance(d, dict):
            return False
        if d.get("workspace_id") != ws_id:
            return False
        if folder_id is not None and d.get("folder_id") != folder_id:
            return False
        if status is not None and d.get("status") != status:
            return False
        if is_trashed is None:
            # default exclude trashed
            if d.get("is_trashed") is True:
                return False
        else:
            if bool(d.get("is_trashed")) != is_trashed:
                return False
        if title is not None:
            dt = d.get("title") or ""
            if not isinstance(dt, str):
                return False
            if title.lower() not in dt.lower():
                return False
        if query is not None:
            q = query.lower()
            dt = (d.get("title") or "")
            cp = (d.get("content_plaintext") or "")
            if not isinstance(dt, str): dt = ""
            if not isinstance(cp, str): cp = ""
            if q not in dt.lower() and q not in cp.lower():
                return False
        return True

    matched = [d for d in docs if _match(d)]

    def _sort_key(d):
        v = d.get(sort)
        if v is None:
            return ""
        return v

    reverse = (order == "desc")
    try:
        matched.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # fall back stable
        pass

    total = len(matched)
    page = matched[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    return _log_and_return({
        "docs": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": limit,
        "cursor": cursor
    })

