    if key is None:
        return _log_and_return(_err("UNAUTHORIZED", "No active API key with required scope docs:write found."), status_code="error", error_code="UNAUTHORIZED")

    window_start = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
    recent = 0
    for r in reqlog:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") == key.get("id") and r.get("timestamp") and r["timestamp"] >= window_start:
            recent += 1
    if recent >= 60:
        return _log_and_return(_err("RATE_LIMIT", "Rate limit exceeded."), status_code="error", error_code="RATE_LIMIT")

    if not isinstance(workspace_id, str) or not re.match(r"^dart_ws_[0-9A-Z]{18,}$", workspace_id):
        return _log_and_return(_err("VALIDATION_ERROR", "workspace_id is invalid."), status_code="error", error_code="VALIDATION_ERROR")
    if workspace_id != key.get("workspace_id"):
        return _log_and_return(_err("UNAUTHORIZED", "API key not authorized for requested workspace."), status_code="error", error_code="UNAUTHORIZED")

    if not isinstance(title, str) or title == "":
        return _log_and_return(_err("VALIDATION_ERROR", "title must be a non-empty string."), status_code="error", error_code="VALIDATION_ERROR")

    if folder_id is not None and not isinstance(folder_id, str):
        return _log_and_return(_err("VALIDATION_ERROR", "folder_id must be a string."), status_code="error", error_code="VALIDATION_ERROR")

    allowed_status = {"draft","published","archived"}
    if status is None:
        status = "draft"
    if status not in allowed_status:
        return _log_and_return(_err("VALIDATION_ERROR", "status is invalid."), status_code="error", error_code="VALIDATION_ERROR")

    if content_text is None:
        content_text = ""
    if not isinstance(content_text, str):
        return _log_and_return(_err("VALIDATION_ERROR", "content_text must be a string."), status_code="error", error_code="VALIDATION_ERROR")

    # server derives plaintext from content_text; if client supplies content_plaintext, it must match derivation
    derived_plain = " ".join(content_text.replace("\r", "\n").split())
    if content_plaintext is not None:
        if not isinstance(content_plaintext, str):
            return _log_and_return(_err("VALIDATION_ERROR", "content_plaintext must be a string."), status_code="error", error_code="VALIDATION_ERROR")
        client_norm = " ".join(content_plaintext.replace("\r", "\n").split())
        if client_norm != derived_plain:
            return _log_and_return(_err("VALIDATION_ERROR", "content_plaintext must match server-derived plaintext from content_text."), status_code="error", error_code="VALIDATION_ERROR")

    # workspace must exist and be active/suspended? visibility: must exist; deleted not allowed
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if ws is None or ws.get("status") == "deleted":
        return _log_and_return(_err("NOT_FOUND", "Workspace not found."), status_code="error", error_code="NOT_FOUND")

    docs = _load("docs.json")
    if not isinstance(docs, list):
        docs = []

    # id generation
    def _gen_id(prefix):
        import secrets, string
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(secrets.choice(alphabet) for _ in range(18))

    new_id = _gen_id("dart_doc_")
    existing_ids = {d.get("id") for d in docs if isinstance(d, dict)}
    while new_id in existing_ids:
        new_id = _gen_id("dart_doc_")

    # choose created_by / updated_by as some active user in workspace (optional nullable)
    users = _load("users.json")
    actor_id = None
    if isinstance(users, list):
        for u in users:
            if isinstance(u, dict) and u.get("workspace_id") == workspace_id and u.get("status") == "active":
                actor_id = u.get("id")
                break

    doc = {
        "id": new_id,
        "workspace_id": workspace_id,
        "folder_id": folder_id,
        "title": title,
        "content_text": content_text,
        "content_plaintext": derived_plain,
        "status": status,
        "is_trashed": False,
        "trashed_at": None,
        "created_by_user_id": actor_id,
        "updated_by_user_id": actor_id,
        "created_at": now,
        "updated_at": now,
    }

    docs.append(doc)
    _save("docs.json", docs)
    return _log_and_return({"doc": doc})

def get_doc(doc_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, api_key_id=None, workspace_id=None, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status,
                "error_code": error_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_z(),
            }
        )
        _save("request_logs.json", logs)

    def _has_scope(scopes, required):
        if not required:
            return True
        if not isinstance(scopes, list):
            return False
        s = set([x for x in scopes if isinstance(x, str)])
        req = set(required)
        if req.issubset(s):
            return True
        if any(r.endswith(":read") for r in req) and ("*:read" in s or "*:*" in s):
            return True
        for r in req:
            if ":" in r:
                res, _act = r.split(":", 1)
                if f"{res}:*" in s or "*:*" in s:
                    return True
        return False

    def _pick_auth_workspace(required_scopes):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            wsid = k.get("workspace_id")
            ws = ws_by_id.get(wsid)
            if not ws or ws.get("status") != "active":
                continue
            if not _has_scope(k.get("scopes"), required_scopes):
                continue
            return k, ws
        return None, None

    try:
        if not isinstance(doc_id, str) or not doc_id.strip():
            _log("get_doc", "error", error_code="VALIDATION_ERROR", message="doc_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "doc_id must be a non-empty string")

        api_key, ws = _pick_auth_workspace(["docs:read"])
        if not api_key:
            _log("get_doc", "error", error_code="UNAUTHORIZED", message="No active API key with docs:read scope found")
            return _err("UNAUTHORIZED", "No active API key authorized for this operation")

        docs = _load("docs.json")
        if not isinstance(docs, list):
            docs = []

        row = None
        for d in docs:
            if not isinstance(d, dict):
                continue
            if d.get("id") == doc_id and d.get("workspace_id") == ws.get("id"):
                row = d
                break

        if not row or row.get("is_trashed") is True:
            _log("get_doc", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND", message="Doc not found")
            return _err("NOT_FOUND", "Doc not found")

        now = _now_z()
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = k.get("updated_at") or now
                    break
            _save("api_keys.json", api_keys)

        _log("get_doc", "ok", api_key_id=api_key.get("id"), workspace_id=ws.get("id"))
        return {"doc": row}
    except Exception as e:
        _log("get_doc", "error", error_code="VALIDATION_ERROR", message=str(e))
        return _err("VALIDATION_ERROR", "Internal error", detail=str(e))

def update_doc(doc_id, title=None, content_text=None, folder_id=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0412000" if __import__("os").path.isdir("./environment_mix/0412000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, api_key_id=None, workspace_id=None, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status,
                "error_code": error_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_z(),
            }
        )
        _save("request_logs.json", logs)

    def _has_scope(scopes, required):
        if not required:
            return True
        if not isinstance(scopes, list):
            return False
        s = set([x for x in scopes if isinstance(x, str)])
        req = set(required)
        if req.issubset(s):
            return True
        if any(r.endswith(":write") for r in req) and ("*:write" in s or "*:*" in s):
            return True
        for r in req:
            if ":" in r:
                res, _act = r.split(":", 1)
                if f"{res}:*" in s or "*:*" in s:
                    return True
        return False

    def _pick_auth_workspace(required_scopes):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            wsid = k.get("workspace_id")
            ws = ws_by_id.get(wsid)
            if not ws or ws.get("status") != "active":
                continue
            if not _has_scope(k.get("scopes"), required_scopes):
                continue
            return k, ws
        return None, None

    def _derive_plaintext(text):
        # Simple normalization: strip common markdown punctuation and normalize whitespace
        import re as _re
        s = text if isinstance(text, str) else ""
        s = _re.sub(r"[`*_>#\[\]\(\)~\-]+", " ", s)
        s = _re.sub(r"\s+", " ", s).strip()
        return s

    try:
        if not isinstance(doc_id, str) or not doc_id.strip():
            _log("update_doc", "error", error_code="VALIDATION_ERROR", message="doc_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "doc_id must be a non-empty string")

        api_key, ws = _pick_auth_workspace(["docs:write"])
        if not api_key:
            _log("update_doc", "error", error_code="UNAUTHORIZED", message="No active API key with docs:write scope found")
            return _err("UNAUTHORIZED", "No active API key authorized for this operation")

        docs = _load("docs.json")
        if not isinstance(docs, list):
            docs = []

        idx = None
        for i, d in enumerate(docs):
            if isinstance(d, dict) and d.get("id") == doc_id and d.get("workspace_id") == ws.get("id"):
                idx = i
                break
        if idx is None:
            _log("update_doc", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND", message="Doc not found")
            return _err("NOT_FOUND", "Doc not found")

        doc = docs[idx]
        if doc.get("is_trashed") is True:
            _log("update_doc", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="INVALID_TRANSITION", message="Cannot update a trashed doc")
            return _err("INVALID_TRANSITION", "Cannot update a trashed doc")

        updates = {}
        if title is not None:
            if not isinstance(title, str) or not title.strip():
                _log("update_doc", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="title must be a non-empty string")
                return _err("VALIDATION_ERROR", "title must be a non-empty string")
            updates["title"] = title

        if content_text is not None:
            if not isinstance(content_text, str):
                _log("update_doc", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="content_text must be a string")
                return _err("VALIDATION_ERROR", "content_text must be a string")
            updates["content_text"] = content_text
            updates["content_plaintext"] = _derive_plaintext(content_text)

        if folder_id is not None:
            if not isinstance(folder_id, str):
                _log("update_doc", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="folder_id must be a string")
                return _err("VALIDATION_ERROR", "folder_id must be a string")
            updates["folder_id"] = folder_id

        if not updates:
            _log("update_doc", "error", api_key_id=api_key.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", message="No fields to update")
            return _err("VALIDATION_ERROR", "No fields to update")

        now = _now_z()
        for k, v in updates.items():
            doc[k] = v
        doc["updated_at"] = now

        docs[idx] = doc
        _save("docs.json", docs)

        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = k.get("updated_at") or now
                    break
            _save("api_keys.json", api_keys)

        _log("update_doc", "ok", api_key_id=api_key.get("id"), workspace_id=ws.get("id"))
        return {"doc": doc}
    except Exception as e:
        _log("update_doc", "error", error_code="VALIDATION_ERROR", message=str(e))
        return _err("VALIDATION_ERROR", "Internal error", detail=str(e))

